def squash(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    parts = []
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        count = j - i
        esc = "\\" + c if ("0" <= c <= "9" or c == "\\") else c
        if count >= 3:
            parts.append(str(count))
            parts.append(esc)
        else:
            parts.append(esc * count)
        i = j
    return "".join(parts)
